import { useEffect } from 'react';

import useOnDelete from './useOnDelete';
import useDeletableDates from './useDeletableDates';
import useDeleteDialog from './useDeleteDialog';

import type { OnDeleteProps } from './types';

type DeleteProps = Pick<OnDeleteProps, 'areTrashedDates' | 'onClose'>;

const Delete: React.FC<DeleteProps> = ({ areTrashedDates, onClose }) => {
	const { deletableIds, lastRelatedCount, hasNoDeletableDates } = useDeletableDates(areTrashedDates);

	const onDelete = useOnDelete({
		idsToDelete: deletableIds,
		areTrashedDates,
		onClose,
	});

	const { confirmationDialog, onOpen } = useDeleteDialog({
		areTrashedDates,
		hasNoDeletableDates,
		lastRelatedCount,
		onDelete,
		onClose,
	});

	// eslint-disable-next-line react-hooks/exhaustive-deps
	useEffect(() => onOpen(), []);

	return <>{confirmationDialog}</>;
};

export default Delete;
