import { useMemo } from 'react';

import { __, _n, sprintf } from '@eventespresso/i18n';
import { useConfirmationDialog } from '@eventespresso/ui-components';

type Props = {
	areTrashedDates: boolean;
	hasNoDeletableDates: boolean;
	lastRelatedCount: number;
	onDelete: VoidFunction;
	onClose: VoidFunction;
};

const useDeleteDialog = ({ areTrashedDates, hasNoDeletableDates, lastRelatedCount, onDelete, onClose }: Props) => {
	const title = useMemo(() => {
		if (hasNoDeletableDates) {
			return __('Cannot Delete Datetimes');
		}

		return areTrashedDates ? __('Delete Datetimes Permanently') : __('Trash Datetimes');
	}, [areTrashedDates, hasNoDeletableDates]);

	const skippedReasons = useMemo(() => {
		if (lastRelatedCount === 0) {
			return [];
		}

		return [
			sprintf(
				/* translators: %d: number of datetimes that will be skipped */
				_n(
					'%d datetime is the only datetime assigned to one or more tickets and cannot be permanently deleted.',
					'%d datetimes are the only datetimes assigned to one or more tickets and cannot be permanently deleted.',
					lastRelatedCount
				),
				lastRelatedCount
			),
		];
	}, [lastRelatedCount]);

	const mainText = useMemo(() => {
		if (hasNoDeletableDates) {
			return __('None of the selected datetimes can be permanently deleted.');
		}

		return areTrashedDates
			? __('Are you sure you want to permanently delete these datetimes? This action can NOT be undone!')
			: __('Are you sure you want to trash these datetimes?');
	}, [areTrashedDates, hasNoDeletableDates]);

	const message = useMemo(
		() => (
			<>
				<p>{mainText}</p>

				{skippedReasons.length > 0 && (
					<>
						<p>
							<strong>{__('Note:')}</strong>{' '}
							{hasNoDeletableDates
								? __('These datetimes cannot be deleted:')
								: __('The following datetimes will be skipped:')}
						</p>

						{skippedReasons.map((reason) => (
							<p key={reason}>• {reason}</p>
						))}
					</>
				)}
			</>
		),
		[mainText, skippedReasons, hasNoDeletableDates]
	);

	return useConfirmationDialog({
		message,
		title,
		onConfirm: hasNoDeletableDates ? onClose : onDelete,
		onCancel: onClose,
		yesButtonText: hasNoDeletableDates ? __('Close') : undefined,
	});
};

export default useDeleteDialog;
