import { useBulkEdit } from '@eventespresso/services';
import { useFilterDeletableEntities } from '@edtrHooks/deletableEntities';

const useDeletableDates = (areTrashedDates: boolean) => {
	const { getSelected } = useBulkEdit();
	const selectedIds = getSelected();

	const lastRelatedIds = useFilterDeletableEntities('datetimes', areTrashedDates ? selectedIds : [], 'tickets');
	const lastRelatedCount = areTrashedDates ? selectedIds.length - lastRelatedIds.length : 0;

	const deletableIds = areTrashedDates ? lastRelatedIds : selectedIds;
	const hasNoDeletableDates = areTrashedDates && deletableIds.length === 0;

	return {
		deletableIds,
		lastRelatedCount,
		hasNoDeletableDates,
	};
};

export default useDeletableDates;
